import json
from pathlib import Path
p=Path('/workspace/sites/olympiad-atlas')
new=[]
def add(year,num,rating,topic,tags,statement,reason,shared=None,comp='USAJMO'):
 url=f'https://web.evanchen.cc/exams/{"JMO" if comp=="USAJMO" else "USAMO"}-{year}-notes.pdf'
 app=[dict(competition=comp,year=year,number=str(num))]
 if shared:app.append(dict(competition='USAMO',year=year,number=str(shared)))
 new.append(dict(id=f'us-{comp.lower()}-{year}-{num}',country='United States',competition=comp,year=year,number=str(num),statement=statement,solution=f'[View Evan Chen’s worked solution notes]({url}).',sourceUrl=url,solutionUrl=url,solutionKind='source-link',topic=topic,tags=tags.split('|'),difficulty=rating,ratingReason=reason,reviewStatus='individually-assessed',notes='Statement restated in original wording. Evan Chen’s author-maintained notes checked; these are not labelled official solutions.',appearances=app))
add(2023,1,6,'Number theory','Factorisation|Diophantine equations|Identities',r'Find all positive integer triples $(x,y,z)$ satisfying $2(x+y+z+2xyz)^2=(2xy+2yz+2zx+1)^2+2023$.','Expanding reveals an unexpectedly useful factorisation into (2x squared−1)(2y squared−1)(2z squared−1). Once found, the small factorisation of 2023 finishes the problem. Discovering or deliberately seeking the identity is the main challenge.')
add(2023,2,4.5,'Geometry','Power of a point|Midpoints|Cyclic quadrilaterals',r'In acute triangle $ABC$, let $M$ be the midpoint of $BC$, and let $P$ be the foot of the perpendicular from $C$ to $AM$. Circle $ABP$ meets line $BC$ again at $Q\ne B$. If $N$ is the midpoint of $AQ$, prove $NB=NC$.','Adding the altitude foot from A gives a second cyclic quadrilateral. Equal powers from M show that Q is the reflection of this foot across M; a midpoint line then yields the required perpendicular bisector. This is a compact linked construction.',shared=1)
add(2023,4,5.5,'Combinatorics','Games|Strategy|Grid colouring',r'On an initially white infinite square grid, Blake colours one white cell blue, then Ruby colours two white cells red, and they repeat in that order. Blake may stop the game and scores the area of the largest simple polygon made entirely of blue unit cells. What score can Blake guarantee?','Growing a connected blue region gives the lower bound from its available neighbours. For the matching upper bound, Ruby partitions the grid into 2-by-2 blocks and forbids adjacent blue cells inside each block, which confines every connected blue region. Both strategies need verification.')
add(2023,5,6,'Number theory','Games|Valuations|Termination',r'Fix positive integers $a,N$ and put $N$ positive integers on a board. Alice moves first, adding $a$ to one entry; Bob then halves one even entry. They alternate, and the game ends when Bob has no legal move. Suppose Bob can force termination against every Alice strategy. Prove that every possible sequence of legal moves terminates, regardless of both players’ choices.','The exponent of 2 in each entry gives a sharp dichotomy. If every exponent is below that of a, their sum decreases; otherwise Alice can protect one entry and perpetuate the game. Discovering and proving this stronger classification resolves the quantifiers.',shared=4)
add(2023,6,6.5,'Geometry','Radical axes|Reflection|Angle bisectors',r'An isosceles triangle $ABC$, with $AB=AC$, lies on circle $\omega$. Choose $D$ inside $BC$ with $BD\ne DC$, and let ray $AD$ meet $\omega$ again at $E$. Choose $F\in\omega$, $F\ne E$, with $\angle DFE=90^\circ$. If line $FE$ meets rays $AB,AC$ at $X,Y$, prove $\angle XDE=\angle EDY$.','The circles through ABD and ACD have equal radii and are reflections in AD. A third circle with diameter DE shares that symmetry, so the corresponding radical axes are reflected lines. Identifying XD and YD as those axes is the decisive reinterpretation.')
add(2022,1,4.5,'Number theory','Modular arithmetic|Progressions|Squarefree integers',r'For which positive integers $m$ is there a nonconstant infinite sequence of residue classes modulo $m$ that is both an arithmetic progression with a fixed common difference and a geometric progression with a fixed common ratio?','Three consecutive terms force the square of the common difference to vanish modulo m. Squarefreeness then gives necessity; conversely a square prime factor supplies a nonzero difference whose square is zero, and starting at 1 gives a valid geometric progression.')
add(2022,2,6,'Combinatorics','Averaging|Permutations|Discrete continuity',r'For positive integers $a,b$, colour an $(a+b+1)\times(a+b+1)$ grid amber or bronze. There are at least $a^2+ab-b$ amber cells and at least $b^2+ab-a$ bronze cells. Prove that one can select $a$ amber and $b$ bronze cells with no two in the same row or column.','Averaging over permutation transversals gives one with enough amber cells and another with enough bronze cells. Transpositions alter the amber count by at most two; the extra row and column allow a discrete intermediate-value argument to hit a suitable count.',shared=1)
add(2022,3,7,'Geometry','Area invariants|Vectors|Adjacent swaps',r'Let $b,w\ge2$ and $n=b+w$. The sides of a regular $2n$-gon of side $1$ are made from $2b$ black and $2w$ white rods, with parallel sides having the same colour. Translate the black rods, without rotating them, to form a convex $2b$-gon $B$, and similarly form a convex $2w$-gon $W$. Prove that $[B]-[W]$ depends only on $b,w$, not on the colouring.','The useful invariant is established under swapping neighbouring opposite-colour direction pairs. The resulting area changes are parallelograms; a diameter and equal-length vectors show that the changes cancel. Turning a global rearrangement question into this local area identity is demanding.',shared=2)
add(2022,4,5.5,'Geometry','Rhombi|Perpendicular bisectors|Construction',r'Let $ABCD$ be a rhombus. Point $K$ lies inside it and $L$ outside it, with $KA=KB=LC=LD$. Prove that some $X\in AC$ and $Y\in BD$, on the full lines, make $KXLY$ a rhombus.','The congruent triangles at opposite sides imply a translation relation. Choose X and Y on the perpendicular bisector of KL and show their midpoint is the midpoint of KL using the original rhombus’s perpendicular diagonals. The proof requires choosing the right construction, not only finding equal sides.')
add(2022,5,4.5,'Number theory','Primes|Difference of squares|Bounds',r'Find all prime pairs $(p,q)$ for which both $p-q$ and $pq-q$ are perfect squares, with $0$ allowed as a square.','Subtracting the two square equations gives a product divisible by p. Bounds on the square roots force their sum to equal p, and parity then forces q=2. A final small congruence finishes the classification.',shared=4)
add(2022,6,6.5,'Algebra','Complex numbers|Recurrences|Growth|Sum of squares',r'For complex numbers $a_0,b_0,c_0$, define $a_{n+1}=a_n^2+2b_nc_n$, $b_{n+1}=b_n^2+2c_na_n$, and $c_{n+1}=c_n^2+2a_nb_n$. If $\max(|a_n|,|b_n|,|c_n|)\le2022$ for every $n\ge0$, prove $|a_0|^2+|b_0|^2+|c_0|^2\le1$.','The sum of squared moduli at the next step is at least the square of its current value, via an exact nonnegative modulus-square identity. Any initial value greater than one would therefore grow without bound. Finding the correct quadratic quantity and handling conjugates are the main obstacles.')
add(2020,1,4.5,'Combinatorics','Inversions|Sorting|Termination',r'Arrange $n\ge2$ books in increasing height order; all heights are distinct, and all widths are distinct. Repeatedly swap adjacent books whenever the left book is both wider and shorter than the right one. Prove that every choice of moves terminates and leaves the books in increasing width order.','Width inversions decrease at every swap. To prove the final order, one must also track the relative order of an individual pair: a pair inverted in both height and width could never have crossed, contradicting the initial height order.')
add(2020,2,6.5,'Geometry','Loci|Tangency|Homothety',r'Let $\omega$ be the incircle of a fixed equilateral triangle $ABC$. A variable tangent to $\omega$ meets the interiors of $BC,CA$ at $P,Q$. Find the locus of all points $R$ satisfying $PR=PA$ and $QR=QB$.','A homothety centred at the incenter identifies one of the two circle intersections from the moving tangency point; reflecting across the tangent gives the other. The full solution must describe both open arcs and justify that every point on them occurs.')
add(2020,3,7,'Combinatorics','Spatial geometry|Packing|Extremal constructions',r'A $2020\times2020\times2020$ cube has a unit-square grid on every face. Place a positive number of $1\times1\times2020$ beams inside it, with their square ends on opposite grid cells and disjoint interiors. Each of the four long faces of every beam must have interior contact with a cube face or the interior of another beam’s face. What is the least possible number of beams?','Counting beams in the three coordinate directions and examining every layer gives pairwise lower bounds. A sharp arrangement must interlace three families of beams while supplying contact on all four long faces; verifying that construction adds genuine spatial complexity.',shared=2)
add(2020,4,4.5,'Geometry','Cyclic quadrilaterals|Circumcentres|Angle chasing',r'A convex cyclic quadrilateral $ABCD$ satisfies $DA<AB=BC<CD$. Points $E\in CD$ and $F\in AB$ satisfy $BE\perp AC$ and $EF\parallel BC$. Prove $FB=FD$.','The parallel line and equal adjacent chords first give FE=FB. Comparing the angle at D with the central angle at F then shows that D lies on the same circle centred at F. The auxiliary interpretation of F as a circumcentre keeps the proof short.')
add(2020,5,6,'Number theory','Lattice points|Determinants|Extremal induction',r'Choose $100$ distinct ordered pairs $(a_i,b_i)$ of nonnegative integers. What is the greatest possible number of index pairs $i<j$ satisfying $|a_ib_j-a_jb_i|=1$?','Regard the pairs as lattice points and remove one farthest from the origin. Its unit-determinant neighbours lie on two parallel lattice lines, with at most one allowable point on each. This gives an induction bound, matched by a simple row of lattice points and one extra point.',shared=4)
add(2020,6,6.5,'Algebra','Multivariable polynomials|Induction|Monomials',r'Let $n\ge2$. A nonconstant real polynomial $P(x_1,\ldots,x_n)$ vanishes whenever any two arguments are equal. Prove that its expansion contains at least $n!$ distinct nonzero monomial terms.','After removing common variable factors, setting one variable to zero gives a nonzero lower-dimensional polynomial. No monomial can omit two variables, so the n inductive term counts are disjoint. Recognising this zero-specialisation counting argument is the key insight.')
add(2020,1,5.5,'Geometry','Circumcentres|Area minimisation|Projection',r'Fix an acute triangle $ABC$ on a circle with centre $O$. Choose $X$ on the open minor arc $AB$ and put $D=CX\cap AB$. Let $O_1,O_2$ be the circumcentres of $ADX,BDX$. Determine all $X$ that minimise the area of $OO_1O_2$.','The circumcentre lines expose a base whose projection onto AB is half of AB and an altitude equal to half of CD. Two geometric lower bounds become equalities together when CX is perpendicular to AB. Finding these useful projections is the principal step.',comp='USAMO')

data=json.loads((p/'data/americas.json').read_text());ids={x['id'] for x in new}
data=[x for x in data if x['id'] not in ids]+new
(p/'data/americas.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
c=json.loads((p/'research/americas-coverage.json').read_text())
full={2023:[6,4.5,7.5,5.5,6,6.5],2022:[4.5,6,7,5.5,4.5,6.5],2020:[4.5,6.5,7,4.5,6,6.5]}
c['fullyScreened']=[x for x in c['fullyScreened'] if not(x['competition']=='USAJMO' and x['year'] in full)]
for year,ratings in full.items():c['fullyScreened'].append(dict(competition='USAJMO',year=year,ratings=ratings,source=f'https://web.evanchen.cc/exams/JMO-{year}-notes.pdf'))
for year,ratings in {2023:{'1':4.5,'4':6},2022:{'1':6,'2':7,'4':4.5},2020:{'1':5.5,'2':7,'4':6}}.items():
 old=next((x for x in c['partiallyScreened'] if (x['competition'],x['year'])==('USAMO',year)),None)
 if old:old['ratings'].update(ratings)
 else:c['partiallyScreened'].append(dict(competition='USAMO',year=year,ratings=ratings,pending=[str(i) for i in range(1,7) if str(i) not in ratings]))
c['papersScreened']=len(c['fullyScreened'])
c['problemAppearancesScreened']=sum(len(x['ratings']) for x in c['fullyScreened']+c['partiallyScreened'])
c['uniqueIncluded']=len(data)
c['gaps'][1]='US: USAMO 2008 Q3, 2009 Q3 and most years outside 2006–2014 remain pending, except listed recent questions. USAJMO 2020, 2022–2026 fully screened; 2021 partially screened; other years pending.'
(p/'research/americas-coverage.json').write_text(json.dumps(c,ensure_ascii=False,indent=2)+'\n')
print('Total',len(data))
